<script setup>
import {ref,computed,onMounted} from 'vue'
import {workspaceRequest,API_BASE} from '../api/client'
import {useAppContext} from '../composables/useAppContext'
import TemplateLibrary from '../components/TemplateLibrary.vue'
import MKHPImporter from '../components/MKHPImporter.vue'
const props=defineProps({initialTab:{type:String,default:'settings'}})
const app=useAppContext(),tab=ref(props.initialTab),status=ref(''),busy=ref(false),settings=ref(null),trash=ref([]),backups=ref(null),projects=ref([]),projectId=ref('')
const en=computed(()=>app.locale==='en'),label=(zh,enText)=>en.value?enText:zh
const fresh=()=>({title:'',platform:'',market:'',currency:'CNY',own_price:null,competitors:[],conclusion:''})
const research=ref(fresh()),stats=ref(null)
const currentPassword=ref(''),newPassword=ref(''),repeatPassword=ref('')
async function savePassword(){await perform(async()=>{if(newPassword.value!==repeatPassword.value)throw new Error(label('两次密码不一致','Passwords do not match'));await workspaceRequest('/auth/password','POST',{current_password:currentPassword.value,new_password:newPassword.value});currentPassword.value='';newPassword.value='';repeatPassword.value='';settings.value.password_configured=true;status.value=label('密码已保存，其他设备已退出。此设备保持登录。','Password saved. Other devices signed out; this device remains signed in.')})}
function competitor(){research.value.competitors.push({name:'',url:'',collected_on:new Date().toISOString().slice(0,10),price:0,rating:null,reviews:null,strengths:'',weaknesses:''})}
async function perform(fn){if(busy.value)return;busy.value=true;status.value='';try{await fn()}catch(e){status.value=e.message}finally{busy.value=false}}
async function load(){settings.value=await workspaceRequest('/workspace/settings');trash.value=(await workspaceRequest('/assets/trash')).items;projects.value=(await workspaceRequest('/workspace/research')).items;if(settings.value.admin)backups.value=await workspaceRequest('/workspace/backups')}
onMounted(()=>perform(load))
async function saveSettings(){await perform(async()=>{const v=await workspaceRequest('/workspace/settings','PUT',settings.value.preferences);app.theme=v.theme;app.locale=v.locale;status.value=label('设置已保存','Settings saved')})}
async function restoreAsset(id){await perform(async()=>{await workspaceRequest(`/assets/${id}/restore`,'POST',{});await load();status.value=label('图片已恢复','Image restored')})}
async function backup(action,id=''){let confirmation='';if(action==='restore'){confirmation=window.prompt(label('恢复会替换整站数据并退出所有登录。输入“恢复整站”确认：','Restoring replaces site data and signs everyone out. Type 恢复整站 to confirm:'))||'';if(confirmation!=='恢复整站')return}await perform(async()=>{await workspaceRequest('/workspace/backups','POST',{action,backup_id:id,confirmation});status.value=label('操作已排队，可稍后点击刷新查看结果。恢复期间网站会短暂中断。','Operation queued. Refresh for status. Restore briefly interrupts the site.');await load()})}
function edit(item){projectId.value=item.project_id;const {project_id,statistics,data_notice,updated_at,...value}=item;research.value=JSON.parse(JSON.stringify(value));stats.value=statistics}
async function saveResearch(){await perform(async()=>{const data=await workspaceRequest('/workspace/research'+(projectId.value?'/'+projectId.value:''),projectId.value?'PUT':'POST',research.value);projectId.value=data.project_id;stats.value=data.statistics;projects.value=(await workspaceRequest('/workspace/research')).items;status.value=label('调研已保存，统计已更新','Research saved; comparison updated')})}
async function deleteResearch(){if(!window.confirm(label('删除这个调研项目？','Delete this research project?')))return;await perform(async()=>{await workspaceRequest('/workspace/research/'+projectId.value,'DELETE');projectId.value='';research.value=fresh();stats.value=null;await load()})}
function jsonExport(){const blob=new Blob([JSON.stringify(research.value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='mhp-research.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function importJson(event){const file=event.target.files[0];if(!file)return;await perform(async()=>{if(file.size>200000)throw new Error('文件不能超过200KB');const value=JSON.parse(await file.text());if(!Array.isArray(value.competitors))throw new Error('无效调研文件');research.value=value;projectId.value='';stats.value=null});event.target.value=''}
</script>
<template>
<main class="workspace-center">
 <header><div><small>MHP WORKSPACE</small><h1>{{ tab==='research'?'MKHP · '+label('市场调研与竞品分析','Market & competitor research'):label('工作空间','Workspace') }}</h1></div><button @click="app.showView('home')">{{ label('返回首页','Home') }}</button></header>
 <p v-if="status" role="status" class="notice">{{ status }}</p>
 <p v-if="busy">{{ label('处理中…','Working…') }}</p>
 <template v-if="tab==='settings'&&settings">
 <section><h2>{{ label('账号登录与设备','Account & device access') }}</h2><p>{{ settings.password_configured?label('此账号已设置登录密码。当前设备将自动保持登录；主动退出或清理资料后用密码登录。','Password configured. This device stays signed in until you sign out or clear its data.'):label('旧账号无需重新注册。请在这里设置一次登录密码，之后换设备也可直接用密码登录。','Existing accounts do not need to register again. Set a password here once to sign in on other devices.') }}</p><form @submit.prevent="savePassword"><div class="fields"><label v-if="settings.password_configured">{{ label('当前密码','Current password') }}<input type="password" autocomplete="current-password" v-model="currentPassword" required maxlength="128" /></label><label>{{ label('新密码','New password') }}<input type="password" autocomplete="new-password" v-model="newPassword" required minlength="10" maxlength="128" /></label><label>{{ label('确认新密码','Confirm new password') }}<input type="password" autocomplete="new-password" v-model="repeatPassword" required minlength="10" maxlength="128" /></label></div><button :disabled="busy">{{ label('保存登录密码','Save sign-in password') }}</button></form></section>
 <section><h2>{{ label('个人偏好','Preferences') }}</h2><div class="fields">
 <label>{{ label('主题','Theme') }}<select v-model="settings.preferences.theme"><option value="dark">{{ label('深色','Dark') }}</option><option value="light">{{ label('浅色','Light') }}</option></select></label>
 <label>{{ label('界面语言','Language') }}<select v-model="settings.preferences.locale"><option value="zh">中文</option><option value="en">English</option></select></label>
 <label>{{ label('默认输出长边','Default output long edge') }}<select v-model="settings.preferences.resolution"><option>1200</option><option>2000</option></select></label>
 </div><button :disabled="busy" @click="saveSettings">{{ label('保存设置','Save preferences') }}</button></section>
 <section><h2>{{ label('服务与版本','Service status') }}</h2><p>{{ settings.version }}</p><div class="fields"><p v-for="(ready,name) in settings.services" :key="name">{{ name }} · {{ ready?label('已配置（待真实调用验证）','Configured; live call not verified'):label('未配置或关闭','Not configured / disabled') }}</p></div></section>
 <section><h2>{{ label('图片回收站','Image trash') }}</h2><p>{{ label('删除的原图从素材列表移除；已有生成结果保留。可在此恢复原图。','Deleted originals leave the material list. Existing results remain. Restore originals here.') }}</p><p v-if="!trash.length">{{ label('回收站为空','Trash is empty') }}</p><div class="list-row" v-for="item in trash" :key="item.asset_id"><span>{{ item.filename }}</span><button :disabled="busy" @click="restoreAsset(item.asset_id)">{{ label('恢复图片','Restore') }}</button></div></section>
 <section v-if="settings.admin&&backups"><h2>{{ label('自动备份与整站恢复（管理员）','Backups & site restore (admin)') }}</h2><p>{{ backups.policy }}</p><p>{{ label('后台服务','Worker') }} · {{ backups.worker_ready?label('运行中','Ready'):label('未就绪','Unavailable') }}</p><button :disabled="busy||!backups.worker_ready" @click="backup('backup')">{{ label('立即备份','Back up now') }}</button> <button :disabled="busy" @click="perform(load)">{{ label('刷新状态','Refresh') }}</button>
 <div class="list-row" v-for="item in backups.items" :key="item.backup_id"><span>{{ item.backup_id }} · {{ (item.bytes/1048576).toFixed(1) }} MB</span><button :disabled="busy||!backups.worker_ready" @click="backup('restore',item.backup_id)">{{ label('恢复此备份','Restore backup') }}</button></div><p v-for="op in backups.operations" :key="op.operation_id">{{ op.action }} · {{ op.state }} · {{ op.message }}</p></section>
 </template>
 <section v-if="tab==='templates'"><TemplateLibrary /></section>
 <template v-if="tab==='research'">
 <MKHPImporter />
 <section><h2>{{ label('调研项目','Research projects') }}</h2><button @click="projectId='';research=fresh();stats=null">{{ label('新建调研','New research') }}</button><div class="project-list"><button v-for="item in projects" :key="item.project_id" @click="edit(item)">{{ item.title }} · {{ item.statistics.samples }} {{ label('个样本','samples') }}</button></div></section>
 <section><h2>{{ label('市场与竞品数据','Market evidence') }}</h2><p>{{ label('录入你实际采集的数据，保留来源链接与日期。系统计算同币种样本统计；不会自动抓取平台实时数据，也不会把评价数推测为销量。','Enter collected evidence with source URLs and dates. Comparisons use one currency. No automatic live scraping or sales estimates from review counts.') }}</p>
 <div class="fields"><label>{{ label('项目名称','Project title') }}<input v-model="research.title" maxlength="120" /></label><label>{{ label('平台','Platform') }}<input v-model="research.platform" maxlength="100" placeholder="Ozon / WB / Amazon" /></label><label>{{ label('目标市场','Market') }}<input v-model="research.market" maxlength="100" /></label><label>{{ label('币种（所有价格一致）','Currency (all prices)') }}<select v-model="research.currency"><option v-for="v in ['CNY','RUB','USD','EUR']" :key="v">{{ v }}</option></select></label><label>{{ label('自己的商品价格','Your price') }}<input type="number" min="0" step="0.01" v-model.number="research.own_price" @change="research.own_price=research.own_price===''?null:research.own_price" /></label></div>
 <article v-for="(item,index) in research.competitors" :key="index"><h3>{{ label('竞品','Competitor') }} {{ index+1 }}</h3><div class="fields"><label>{{ label('名称','Name') }}<input v-model="item.name" maxlength="120" /></label><label>{{ label('来源网址','Source URL') }}<input v-model="item.url" type="url" placeholder="https://…" /></label><label>{{ label('采集日期','Collected date') }}<input type="date" v-model="item.collected_on" /></label><label>{{ label('价格','Price') }}<input type="number" min="0" step="0.01" v-model.number="item.price" /></label><label>{{ label('评分（选填，0–5）','Rating (optional, 0–5)') }}<input type="number" min="0" max="5" step="0.1" v-model.number="item.rating" @change="item.rating=item.rating===''?null:item.rating" /></label><label>{{ label('评价数（选填）','Review count (optional)') }}<input type="number" min="0" step="1" v-model.number="item.reviews" @change="item.reviews=item.reviews===''?null:item.reviews" /></label><label>{{ label('优势','Strengths') }}<textarea v-model="item.strengths" maxlength="1000" /></label><label>{{ label('不足/差异机会','Weaknesses / opportunities') }}<textarea v-model="item.weaknesses" maxlength="1000" /></label></div><button @click="research.competitors.splice(index,1)">{{ label('移除此竞品','Remove competitor') }}</button></article>
 <button :disabled="research.competitors.length>=50" @click="competitor">{{ label('添加竞品','Add competitor') }}</button><label>{{ label('调研结论与行动计划','Findings & action plan') }}<textarea rows="5" maxlength="10000" v-model="research.conclusion" /></label>
 <p id="research-save-hint" role="status">{{ busy?label('正在处理，请稍候…','Processing, please wait…'):!research.title.trim()?label('请先填写项目名称','Enter a project title first.'):'' }}</p><button :disabled="busy||!research.title.trim()" aria-describedby="research-save-hint" @click="saveResearch">{{ label('保存并分析','Save & compare') }}</button> <button v-if="projectId" :disabled="busy" @click="deleteResearch">{{ label('删除项目','Delete project') }}</button>
 </section>
 <section v-if="stats"><h2>{{ label('价格与定位对比','Price positioning') }}</h2><div class="fields"><p>{{ label('样本数','Samples') }}：{{ stats.samples }}</p><p>{{ label('最低价','Minimum') }}：{{ stats.minimum??'—' }} {{ research.currency }}</p><p>{{ label('最高价','Maximum') }}：{{ stats.maximum??'—' }} {{ research.currency }}</p><p>{{ label('中位价','Median') }}：{{ stats.median??'—' }} {{ research.currency }}</p><p>{{ label('平均价','Mean') }}：{{ stats.average??'—' }} {{ research.currency }}</p><p v-if="stats.own_vs_median_percent!==undefined">{{ label('自身价格相对中位价','Your price vs median') }}：{{ stats.own_vs_median_percent }}%</p></div><p>{{ label('统计基于当前保存的有限样本，不代表整个平台市场；价格差不代表利润。修改数据后请重新保存。','Saved samples do not represent the entire market. Price gaps are not profits. Save again after editing.') }}</p><div class="table-wrap"><table><thead><tr><th>{{ label('竞品','Competitor') }}</th><th>{{ label('价格','Price') }}</th><th>{{ label('评分/评价','Rating / reviews') }}</th><th>{{ label('来源/日期','Source / date') }}</th></tr></thead><tbody><tr v-for="(item,i) in research.competitors" :key="i"><td>{{ item.name }}</td><td>{{ item.price }} {{ research.currency }}</td><td>{{ item.rating??'—' }} / {{ item.reviews??'—' }}</td><td><a :href="/^https?:\/\//.test(item.url)?item.url:undefined" target="_blank" rel="noopener noreferrer">{{ item.collected_on }}</a></td></tr></tbody></table></div></section>
 <section><h2>{{ label('导入与导出','Import / export') }}</h2><button @click="jsonExport">{{ label('导出可编辑JSON','Export editable JSON') }}</button> <a v-if="projectId" :href="`${API_BASE}/api/workspace/research/${projectId}/export`">{{ label('下载竞品对比CSV','Download comparison CSV') }}</a><label>{{ label('导入之前导出的调研JSON','Import a research JSON export') }}<input type="file" accept="application/json,.json" @change="importJson" /></label></section>
 </template>
</main>
</template>
<style>
.workspace-center{position:relative;max-width:1300px;margin-left:var(--sidebar-width);padding:96px 32px 32px;color:var(--text-primary)}.workspace-center header,.workspace-center .list-row{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}.workspace-center section,.workspace-center article{padding:22px;margin:18px 0;border:1px solid var(--border-dim);border-radius:16px;background:var(--bg-card-strong)}.workspace-center h1{font-size:26px}.workspace-center h2{font-size:20px}.workspace-center p{line-height:1.7;overflow-wrap:anywhere}.workspace-center .fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:16px}.workspace-center label{display:flex;flex-direction:column;gap:8px;margin:12px 0}.workspace-center input,.workspace-center select,.workspace-center textarea,.workspace-center button,.template-library input,.template-library button{font:inherit;color:var(--text-primary);background:var(--bg-sidebar);border:1px solid var(--border-dim);border-radius:8px;padding:10px;max-width:100%;min-width:0}.workspace-center button,.template-library button{cursor:pointer}.workspace-center button:disabled{opacity:.5;cursor:not-allowed}.workspace-center .active{border-color:var(--neon-blue)}.workspace-center .notice{padding:14px;background:var(--bg-sidebar);border-left:3px solid var(--neon-blue)}.workspace-center a{color:var(--neon-blue)}.workspace-center .list-row{padding:12px 0;border-bottom:1px solid var(--border-dim)}.workspace-center .project-list{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.table-wrap{overflow:auto}.workspace-center table{width:100%;border-collapse:collapse}.workspace-center td,.workspace-center th{padding:12px;border-bottom:1px solid var(--border-dim);text-align:left}@media(max-width:767px){.workspace-center{margin-left:0;padding:90px 12px 18px}.workspace-center section{padding:14px}.workspace-center h1{font-size:22px}}
</style>
